Layout.Stylesheet:
body { margin: 0; }
p { border: 0.5pt solid black; }
.m-all { margin: 20pt; background-color: lightblue; }
.m-top { margin-top: 15pt; background-color: lightgreen; }
.m-right { margin-right: 30pt; background-color: lightyellow; }
.m-bottom { margin-bottom: 10pt; background-color: lightpink; }
.m-left { margin-left: 40pt; background-color: lightgray; }
.m-shorthand-2 { margin: 10pt 30pt; background-color: lightcoral; }
.m-shorthand-4 { margin: 5pt 10pt 15pt 20pt; background-color: lavender; }
